<?php
session_start();
include 'config.php';
if (!isset($_SESSION['user_id']) || ($_SESSION['role'] ?? '') !== 'admin') { header('Location: login_a.php'); exit(); }
$conn->query("CREATE TABLE IF NOT EXISTS product_substitutions (id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, substitute_product_id INT NOT NULL, reason VARCHAR(255) NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', created_by INT NULL, reviewed_by INT NULL, reviewed_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_product_substitute (product_id, substitute_product_id))");
$message=''; $error=''; $adminId=(int)$_SESSION['user_id'];
if ($_SERVER['REQUEST_METHOD']==='POST') {
    $action=$_POST['action']??''; $id=(int)($_POST['id']??0);
    if ($action==='create') {
        $productId=(int)($_POST['product_id']??0); $substituteId=(int)($_POST['substitute_product_id']??0); $reason=trim($_POST['reason']??'');
        if ($productId<1 || $substituteId<1 || $productId===$substituteId) $error='Choose two different products.';
        else { $stmt=$conn->prepare('INSERT INTO product_substitutions (product_id, substitute_product_id, reason, created_by) VALUES (?, ?, ?, ?) ON DUPLICATE KEY UPDATE reason=VALUES(reason), status="pending", reviewed_by=NULL, reviewed_at=NULL'); if($stmt){$stmt->bind_param('iisi',$productId,$substituteId,$reason,$adminId);$message=$stmt->execute()?'Substitution submitted for approval.':'Unable to save substitution.';$stmt->close();} }
    } elseif (in_array($action,['approve','reject'],true) && $id>0) {
        $status=$action==='approve'?'approved':'rejected'; $stmt=$conn->prepare('UPDATE product_substitutions SET status=?, reviewed_by=?, reviewed_at=NOW() WHERE id=?'); if($stmt){$stmt->bind_param('sii',$status,$adminId,$id);$stmt->execute();$stmt->close();$message='Substitution status updated.';}
    }
}
$products=$conn->query('SELECT id, product_name, sku, barcode, quantity FROM products ORDER BY product_name ASC');
$rows=$conn->query("SELECT s.*, p.product_name original_name, p.quantity original_stock, sp.product_name substitute_name, sp.quantity substitute_stock, sp.sku substitute_sku FROM product_substitutions s JOIN products p ON p.id=s.product_id JOIN products sp ON sp.id=s.substitute_product_id ORDER BY FIELD(s.status,'pending','approved','rejected'), s.created_at DESC");
$currentPage=basename($_SERVER['PHP_SELF']);
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Product Substitutions</title><link rel="stylesheet" href="css/sidebar_owner.css?v=20260905-4"><style>
*{box-sizing:border-box}body{margin:0;background:#f7f8fa;color:#20232a;font-family:'Segoe UI',Tahoma,sans-serif}.content{margin-left:244px;padding:28px;min-height:100vh}.head{margin-bottom:18px}.head h1{margin:0 0 5px;font-size:22px}.head p{margin:0;color:#7b8189;font-size:11px}.panel{background:#fff;border:1px solid #ebedf0;border-radius:9px;padding:16px;margin-bottom:16px;box-shadow:0 2px 10px rgba(25,30,38,.04)}.form{display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:10px;align-items:end}.form label{display:flex;flex-direction:column;gap:5px;color:#626a74;font-size:10px;font-weight:600}.form input,.form select{height:32px;padding:0 9px;border:1px solid #dfe4e9;border-radius:6px;font-size:11px}.button{height:32px;padding:0 12px;border:0;border-radius:6px;background:#ed1740;color:#fff;font-size:10px;font-weight:700;cursor:pointer}.button.approve{background:#15955c}.button.reject{background:#d33b59}.notice{padding:10px 12px;border-radius:7px;margin-bottom:14px;font-size:11px}.success{background:#e9f8ef;color:#278658}.error{background:#ffe8ed;color:#d33b59}.table-scroll{overflow:auto}table{width:100%;min-width:850px;border-collapse:collapse}th,td{padding:10px 8px;border-bottom:1px solid #f0f1f3;text-align:left;font-size:10px;white-space:nowrap}th{background:#fbfcfd;color:#68707a;font-size:9px}.status{padding:4px 7px;border-radius:5px;font-size:9px}.pending{background:#fff5df;color:#a8730d}.approved{background:#e9f8ef;color:#278658}.rejected{background:#ffe8ed;color:#d33b59}.muted{color:#7b8189;font-size:10px}@media(max-width:800px){.content{margin-left:0;padding:20px 14px}.form{grid-template-columns:1fr 1fr}}@media(max-width:500px){.form{grid-template-columns:1fr}}
</style></head><body><?php include 'sidebar_owner.php'; ?><main class="content"><header class="head"><h1>Product Substitution Suggestions</h1><p>Approve pharmacist-reviewed alternatives for out-of-stock medicines.</p></header><?php if($message):?><div class="notice success"><?php echo htmlspecialchars($message);?></div><?php endif;?><?php if($error):?><div class="notice error"><?php echo htmlspecialchars($error);?></div><?php endif;?><section class="panel"><h2 style="font-size:15px;margin:0 0 12px">Create Suggestion</h2><form method="post" class="form"><input type="hidden" name="action" value="create"><label>Out-of-stock product<select name="product_id" required><option value="">Select medicine</option><?php if($products):while($p=$products->fetch_assoc()):?><option value="<?php echo (int)$p['id'];?>"><?php echo htmlspecialchars($p['product_name']);?> (Stock: <?php echo (int)$p['quantity'];?>)</option><?php endwhile;endif;?></select></label><?php $products=$conn->query('SELECT id, product_name, sku, barcode, quantity FROM products ORDER BY product_name ASC');?><label>Alternative product<select name="substitute_product_id" required><option value="">Select alternative</option><?php if($products):while($p=$products->fetch_assoc()):?><option value="<?php echo (int)$p['id'];?>"><?php echo htmlspecialchars($p['product_name']);?> (Stock: <?php echo (int)$p['quantity'];?>)</option><?php endwhile;endif;?></select></label><label>Reason<input name="reason" placeholder="Same active ingredient / strength"></label><button class="button" type="submit">Submit for approval</button></form></section><section class="panel"><h2 style="font-size:15px;margin:0 0 12px">Substitution Review Queue</h2><div class="table-scroll"><table><tr><th>Original product</th><th>Alternative</th><th>Alternative stock</th><th>Reason</th><th>Status</th><th>Action</th></tr><?php if($rows):while($row=$rows->fetch_assoc()):?><tr><td><?php echo htmlspecialchars($row['original_name']);?> <small>(stock: <?php echo (int)$row['original_stock'];?>)</small></td><td><?php echo htmlspecialchars($row['substitute_name']);?> <small>(<?php echo htmlspecialchars($row['substitute_sku']??'');?></small>)</td><td><?php echo (int)$row['substitute_stock'];?></td><td><?php echo htmlspecialchars($row['reason']??'');?></td><td><span class="status <?php echo htmlspecialchars($row['status']);?>"><?php echo ucfirst($row['status']);?></span></td><td><?php if($row['status']==='pending'):?><form method="post" style="display:inline"><input type="hidden" name="id" value="<?php echo (int)$row['id'];?>"><button class="button approve" name="action" value="approve">Approve</button> <button class="button reject" name="action" value="reject">Reject</button></form><?php else:?>—<?php endif;?></td></tr><?php endwhile;else:?><tr><td colspan="6" class="muted">No substitution suggestions yet.</td></tr><?php endif;?></table></div></section></main></body></html>
